INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine Datei immer ein Textdokument?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch Bilder, Programme sein"}, {"text": "Ja", "correct": false, "because": "Verschiedene Typen existieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer Datei?', 3, '[{"text": "Daten speichern", "correct": true, "because": "Grundfunktion"}, {"text": "Netzwerk konfigurieren", "correct": false, "because": "Kein Netzwerkfokus"}, {"text": "Hardware reparieren", "correct": false, "because": "Kein Hardware-Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat eine Datei?', 5, '[{"text": "Name", "correct": true, "because": "Identifiziert sie"}, {"text": "Größe", "correct": true, "because": "Gibt Speicherbedarf an"}, {"text": "Farbe", "correct": false, "because": "Kein Dateiattribut"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine Datei hat eine Endung. b) Sie ist immer ausführbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht alle sind Programme"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Arbeit mit Dateien?', 4, '[{"text": "Speicherort", "correct": false, "because": "Wichtig für Zugriff"}, {"text": "Format", "correct": false, "because": "Bestimmt Öffnung"}, {"text": "Monitorgröße", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob jede Datei lesbar ist?', 2, '[{"text": "Nein", "correct": true, "because": "Binärdateien nicht direkt lesbar"}, {"text": "Ja", "correct": false, "because": "Formatabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Attribut zeigt den Dateityp?', 3, '[{"text": "Dateiendung", "correct": true, "because": "Gibt Format an"}, {"text": "Erstellungsdatum", "correct": false, "because": "Nur Zeitangabe"}, {"text": "Besitzer", "correct": false, "because": "Kein Typindikator"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Operationen kann ich mit Dateien durchführen?', 5, '[{"text": "Erstellen", "correct": true, "because": "Neue Datei anlegen"}, {"text": "Löschen", "correct": true, "because": "Entfernt Datei"}, {"text": "Netzwerk konfigurieren", "correct": false, "because": "Kein Dateifokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Dateien haben Metadaten. b) Sie sind immer verschlüsselt. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verschlüsselung optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine Datei?', 4, '[{"text": "Speichermedium", "correct": false, "because": "Speicherort nötig"}, {"text": "Dateisystem", "correct": false, "because": "Organisiert Dateien"}, {"text": "Externer Monitor", "correct": true, "because": "Kein direkter Bedarf"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist jede Datei ein Programm?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Daten wie Texte"}, {"text": "Ja", "correct": false, "because": "Nur bestimmte Typen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Dateitypen gibt es?', 4, '[{"text": "Textdateien", "correct": true, "because": "Speichern Text"}, {"text": "Binärdateien", "correct": true, "because": "Programme, Bilder"}, {"text": "Netzwerkdateien", "correct": false, "because": "Kein Typ"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Dateien ohne Endung nutzlos sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Funktion bleibt"}, {"text": "Ja", "correct": false, "because": "Endung nur Hinweis"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Dateiverwaltung?', 3, '[{"text": "Organisation", "correct": true, "because": "Schneller Zugriff"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Ordnung zählt"}, {"text": "Minimale Größe", "correct": false, "because": "Kontextabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Dateien haben eine Größe. b) Sie sind immer sichtbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Versteckte Dateien möglich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Metadaten gehören zu einer Datei?', 5, '[{"text": "Erstellungsdatum", "correct": true, "because": "Zeigt Zeit"}, {"text": "Größe", "correct": true, "because": "Speicherbedarf"}, {"text": "Farbtiefe", "correct": false, "because": "Bildspezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Dateien unwichtig?', 3, '[{"text": "Speicherort", "correct": false, "because": "Für Zugriff nötig"}, {"text": "Zugriffsrechte", "correct": false, "because": "Schützt Datei"}, {"text": "Tastaturtyp", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann eine Datei ohne Dateisystem existieren?', 3, '[{"text": "Nein", "correct": true, "because": "Dateisystem organisiert"}, {"text": "Ja", "correct": false, "because": "Struktur nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Dateien immer lokal sind?', 2, '[{"text": "Nein", "correct": true, "because": "Auch in Cloud möglich"}, {"text": "Ja", "correct": false, "because": "Ortsunabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Dateiendung?', 4, '[{"text": "Typbestimmung", "correct": true, "because": "Zeigt Format an"}, {"text": "Größenbegrenzung", "correct": false, "because": "Kein Zusammenhang"}, {"text": "Sicherheitsstufe", "correct": false, "because": "Kein Schutz"}]');
